#!/usr/bin/env python3
"""Moteur QuestionnApp en un seul fichier (généré par scripts/build_claude_project.py).

Sert à tester des questions hors de l'application, par exemple dans l'environnement
d'exécution de Claude :

    python3 questionnapp_moteur.py questions.json            # auto-test de chaque question
    python3 questionnapp_moteur.py questions.json --apercu   # + un exemple d'énoncé par question

Depuis Python :

    import questionnapp_moteur as m
    m.selftest(template)          # rapport : status ok / warning / error
    m.preview(template, seed=1)   # énoncé, réponses attendues, variété

Les garde-fous d'exécution (bac à sable) ne sont pas activés ici : ne l'utilisez que pour
tester vos propres questions.
"""

import importlib.util
import json
import sys
import types

_SOURCES = {
    'sandbox': '"""Garde-fous d\'exécution pour le code des modèles (profs) et des élèves.\n\nCe n\'est PAS un bac à sable parfait : en production exposée à Internet, faire\ntourner le moteur dans un conteneur sans réseau (voir QUESTIONNAPP_SANDBOX_CMD\ndans docs/ARCHITECTURE.md). Ici on combine :\n  * limites système (CPU, mémoire, taille de fichiers, nombre de processus) ;\n  * un « audit hook » Python qui bloque réseau, processus, écriture de fichiers,\n    lecture de fichiers hors de la bibliothèque standard, ctypes, etc. ;\n  * un délai maximal côté appelant (le serveur tue le processus).\n"""\n\nimport os\nimport sys\nimport sysconfig\n\ntry:\n    import resource\nexcept ImportError:  # Windows : pas de limites système\n    resource = None\n\n# Modules que le code des modèles et des élèves peut importer.\nALLOWED_IMPORTS = {\n    "math", "random", "itertools", "functools", "collections", "string", "re",\n    "heapq", "bisect", "statistics", "fractions", "decimal", "copy", "typing",\n    "dataclasses", "textwrap", "operator", "sqlite3", "json", "time", "datetime",\n    "array", "enum", "abc", "numbers", "cmath", "pprint", "unicodedata",\n}\n\n_BLOCKED_PREFIXES = (\n    "socket.", "subprocess.", "os.system", "os.exec", "os.spawn", "os.posix_spawn",\n    "os.fork", "os.forkpty", "os.kill", "os.killpg", "os.remove", "os.unlink",\n    "os.rmdir", "os.rename", "os.mkdir", "os.chmod", "os.chown", "os.truncate",\n    "os.symlink", "os.link", "os.putenv", "os.unsetenv", "os.chdir", "os.listdir",\n    "os.scandir", "os.walk", "shutil.", "ctypes.", "urllib.", "http.", "ftplib.",\n    "smtplib.", "webbrowser.", "pty.", "winreg.", "msvcrt.", "code.__new__",\n    "marshal.", "pickle.", "shelve.", "glob.", "setopencodehook",\n    "sys.addaudithook", "sys.setprofile", "sys.settrace", "gc.get_referrers",\n    "gc.get_objects",\n)\n\n_STDLIB_DIRS = tuple(\n    os.path.realpath(p) for p in {\n        sysconfig.get_paths().get("stdlib"),\n        sysconfig.get_paths().get("platstdlib"),\n    } if p\n)\n_ENGINE_DIR = os.path.realpath(os.path.dirname(__file__))\n\n\nclass SandboxViolation(Exception):\n    pass\n\n\n# Vrai pendant l\'exécution du code d\'un élève (et des tests qui l\'appellent) : on y interdit\n# en plus l\'introspection des frames, qui permettrait de lire la réponse attendue.\nSTUDENT = False\n\n_STUDENT_BLOCKED = ("sys._getframe", "sys._current_frames", "sys._getframemodulename", "object.__getattr__",\n                    "gc.", "sys.set", "builtins.input", "cpython.")\n\n\ndef _audit(event, args):\n    if STUDENT and event.startswith(_STUDENT_BLOCKED):\n        raise SandboxViolation(f"opération interdite ({event})")\n    if event == "open":\n        path, mode = args[0], args[1]\n        if isinstance(path, int):  # descripteur déjà ouvert\n            return\n        if mode is not None and any(c in str(mode) for c in "wax+"):\n            raise SandboxViolation("écriture de fichier interdite")\n        real = os.path.realpath(os.fsdecode(path))\n        if not (real.startswith(_STDLIB_DIRS) or real.startswith(_ENGINE_DIR)):\n            raise SandboxViolation("accès aux fichiers interdit")\n        return\n    if event == "import":\n        name = args[0] or ""\n        root = name.split(".")[0]\n        if root not in ALLOWED_IMPORTS and name not in sys.modules and not root.startswith("_"):\n            raise SandboxViolation(f"import du module « {name} » interdit")\n        return\n    if event == "sqlite3.connect":\n        target = str(args[0]) if args else ""\n        if target not in (":memory:", ""):\n            raise SandboxViolation("seules les bases SQLite en mémoire sont autorisées")\n        return\n    for prefix in _BLOCKED_PREFIXES:\n        if event.startswith(prefix):\n            raise SandboxViolation(f"opération interdite ({event})")\n\n\ndef install(cpu_seconds=10, memory_mb=512):\n    """À appeler une seule fois, après les imports nécessaires au moteur."""\n    import importlib\n    for name in sorted(ALLOWED_IMPORTS):  # pré-charge les dépendances transitives\n        try:\n            importlib.import_module(name)\n        except ImportError:\n            pass\n    if resource is not None:\n        def setlim(which, value):\n            try:\n                soft, hard = resource.getrlimit(which)\n                if hard != resource.RLIM_INFINITY:\n                    value = min(value, hard)\n                resource.setrlimit(which, (value, value if hard == resource.RLIM_INFINITY else hard))\n            except (ValueError, OSError):\n                pass\n        setlim(resource.RLIMIT_CPU, cpu_seconds)\n        setlim(resource.RLIMIT_AS, memory_mb * 1024 * 1024)\n        setlim(resource.RLIMIT_FSIZE, 0)\n        if hasattr(resource, "RLIMIT_NPROC"):\n            setlim(resource.RLIMIT_NPROC, 0)\n    sys.setrecursionlimit(3000)\n    sys.addaudithook(_audit)\n',
    'helpers': '"""Fonctions mises à disposition des auteurs de questions dans le code générateur.\n\nToutes les fonctions aléatoires utilisent le générateur seedé de l\'instance :\nune même graine redonne exactement la même question.\n"""\n\nimport contextlib\nimport io\nimport math\nimport random as _random_module\nimport sqlite3\nimport string\nimport textwrap\n\nPRENOMS = [\n    "Alice", "Bilal", "Chloé", "David", "Emma", "Farid", "Gabriel", "Hugo", "Inès",\n    "Jade", "Karim", "Léa", "Mehdi", "Nina", "Oscar", "Paul", "Rose", "Sami",\n    "Théo", "Yasmine", "Zoé", "Lucas", "Manon", "Noah",\n]\nFRUITS = ["pomme", "poire", "kiwi", "banane", "mangue", "cerise", "fraise", "prune", "abricot", "orange"]\nVILLES = ["Paris", "Lyon", "Lille", "Nantes", "Rennes", "Brest", "Nice", "Metz", "Dijon", "Tours", "Caen"]\nNOMS_VARIABLES = ["a", "b", "c", "d", "i", "j", "k", "m", "n", "p", "q", "r", "s", "t", "u", "v", "w", "x", "y", "z"]\nNOMS_LISTES = ["L", "T", "tab", "liste", "valeurs", "nombres", "donnees", "t"]\nNOMS_FONCTIONS = ["f", "g", "h", "mystere", "calcul", "traitement", "fonction", "secret"]\n\n\nclass ExecutionError(Exception):\n    """Erreur levée par le code exécuté via run()/sql_run()."""\n\n\ndef _format_exc(exc):\n    return f"{type(exc).__name__}: {exc}"\n\n\ndef run(code, inputs=None, namespace=None, max_output=20000):\n    """Exécute du code Python et renvoie ce qu\'il affiche (sans le dernier saut de ligne).\n\n    inputs : liste de chaînes renvoyées successivement par input().\n    """\n    feed = list(inputs or [])\n    out = io.StringIO()\n\n    def fake_input(prompt=""):\n        out.write(str(prompt))\n        if not feed:\n            raise ExecutionError("input() appelé mais aucune entrée n\'est prévue")\n        value = str(feed.pop(0))\n        out.write(value + "\\n")\n        return value\n\n    # si `namespace` est fourni, les variables du programme y restent accessibles après exécution\n    ns = namespace if namespace is not None else {}\n    ns.setdefault("__name__", "__main__")\n    ns["input"] = fake_input\n    with contextlib.redirect_stdout(out):\n        exec(compile(textwrap.dedent(code), "<code>", "exec"), ns)\n    text = out.getvalue()\n    if len(text) > max_output:\n        raise ExecutionError("sortie trop longue")\n    return text[:-1] if text.endswith("\\n") else text\n\n\ndef run_error(code, inputs=None):\n    """Exécute du code et renvoie le nom de l\'exception levée, ou None s\'il n\'y en a pas."""\n    try:\n        run(code, inputs)\n    except Exception as exc:  # noqa: BLE001 - on veut justement le type d\'erreur\n        return type(exc).__name__\n    return None\n\n\ndef evaluate(code, expression, inputs=None):\n    """Exécute `code` puis renvoie la valeur de `expression` dans le même espace de noms."""\n    ns = {"__name__": "__main__"}\n    run(code, inputs, ns)\n    return eval(expression, ns)\n\n\ndef sql_connect(setup):\n    db = sqlite3.connect(":memory:")\n    db.executescript(setup)\n    return db\n\n\ndef sql_run(setup, query):\n    """Exécute `setup` (script SQL) dans une base en mémoire puis renvoie les lignes de `query`."""\n    db = sql_connect(setup)\n    try:\n        return [tuple(r) for r in db.execute(query).fetchall()]\n    finally:\n        db.close()\n\n\ndef sql_value(setup, query):\n    """Première colonne de la première ligne du résultat (ou None)."""\n    rows = sql_run(setup, query)\n    return rows[0][0] if rows else None\n\n\ndef _md_cell(v):\n    if v is None:\n        return "NULL"\n    return str(v).replace("|", "\\\\|").replace("\\n", " ")\n\n\ndef md_table(rows, headers=None):\n    """Tableau Markdown à partir d\'une liste de lignes (tuples/listes)."""\n    rows = [list(r) for r in rows]\n    if headers is None:\n        headers = [""] * (len(rows[0]) if rows else 0)\n    lines = ["| " + " | ".join(_md_cell(h) for h in headers) + " |",\n             "|" + "|".join("---" for _ in headers) + "|"]\n    lines += ["| " + " | ".join(_md_cell(c) for c in r) + " |" for r in rows]\n    return "\\n".join(lines)\n\n\ndef sql_table(setup, table, limit=None):\n    """Contenu d\'une table (générée par `setup`) sous forme de tableau Markdown."""\n    db = sql_connect(setup)\n    try:\n        cur = db.execute(f\'SELECT * FROM "{table}"\' + (f" LIMIT {int(limit)}" if limit else ""))\n        headers = [d[0] for d in cur.description]\n        return md_table(cur.fetchall(), headers)\n    finally:\n        db.close()\n\n\ndef sql_schema(setup):\n    """Schéma relationnel lisible : table(col1, col2, ...) pour chaque table."""\n    db = sql_connect(setup)\n    try:\n        tables = [r[0] for r in db.execute(\n            "SELECT name FROM sqlite_master WHERE type=\'table\' AND name NOT LIKE \'sqlite_%\' ORDER BY rowid")]\n        parts = []\n        for t in tables:\n            cols = []\n            for _cid, name, _type, _nn, _dflt, pk in db.execute(f\'PRAGMA table_info("{t}")\'):\n                cols.append(f"__{name}__" if pk else name)\n            fks = {r[3]: (r[2], r[4]) for r in db.execute(f\'PRAGMA foreign_key_list("{t}")\')}\n            cols = [c + (f" → {fks[c][0]}.{fks[c][1]}" if c in fks else "") for c in cols]\n            parts.append(f"- **{t}**({\', \'.join(cols)})")\n        return "\\n".join(parts)\n    finally:\n        db.close()\n\n\ndef sql_quote(value):\n    if value is None:\n        return "NULL"\n    if isinstance(value, (int, float)):\n        return repr(value)\n    return "\'" + str(value).replace("\'", "\'\'") + "\'"\n\n\ndef sql_insert(table, rows):\n    """Script INSERT pour une liste de lignes."""\n    return "\\n".join(\n        f"INSERT INTO {table} VALUES ({\', \'.join(sql_quote(v) for v in r)});" for r in rows)\n\n\ndef tobase(n, base, width=0):\n    """Écriture de l\'entier n en base 2..36 (chiffres en majuscules), complétée à `width` chiffres."""\n    if not 2 <= base <= 36:\n        raise ValueError("base entre 2 et 36")\n    digits = string.digits + string.ascii_uppercase\n    if n == 0:\n        s = "0"\n    else:\n        neg, n, s = n < 0, abs(n), ""\n        while n:\n            n, r = divmod(n, base)\n            s = digits[r] + s\n        s = ("-" if neg else "") + s\n    return s.rjust(width, "0")\n\n\ndef frombase(s, base):\n    return int(str(s).replace(" ", ""), base)\n\n\ndef twos(n, bits):\n    """Représentation en complément à deux de n sur `bits` bits."""\n    if not -(1 << (bits - 1)) <= n < (1 << (bits - 1)):\n        raise ValueError(f"{n} n\'est pas représentable sur {bits} bits")\n    return tobase(n & ((1 << bits) - 1), 2, bits)\n\n\ndef from_twos(s, bits=None):\n    s = str(s).replace(" ", "")\n    bits = bits or len(s)\n    v = int(s, 2)\n    return v - (1 << bits) if s[0] == "1" else v\n\n\ndef group(s, size=4, sep=" "):\n    """Groupe les caractères par paquets depuis la droite : group(\'10110011\') -> \'1011 0011\'."""\n    s = str(s)\n    head = len(s) % size\n    parts = ([s[:head]] if head else []) + [s[i:i + size] for i in range(head, len(s), size)]\n    return sep.join(parts)\n\n\ndef code_block(code, lang="python"):\n    return f"```{lang}\\n{textwrap.dedent(code).strip(chr(10))}\\n```"\n\n\ndef indent(code, n=4):\n    return textwrap.indent(textwrap.dedent(code), " " * n)\n\n\ndef dedent(code):\n    return textwrap.dedent(code).strip("\\n")\n\n\ndef fr(x, decimals=None):\n    """Nombre au format français (virgule décimale)."""\n    if decimals is not None:\n        x = round(x, decimals)\n        s = f"{x:.{decimals}f}"\n    elif isinstance(x, float) and x.is_integer():\n        s = str(int(x))\n    else:\n        s = str(x)\n    return s.replace(".", ",")\n\n\ndef make_random_api(rng):\n    """Fonctions aléatoires liées au générateur seedé `rng`."""\n\n    def randint(a, b):\n        return rng.randint(a, b)\n\n    def randnz(a, b):\n        """Entier aléatoire non nul entre a et b."""\n        if a == 0 == b:\n            raise ValueError("intervalle réduit à 0")\n        while True:\n            v = rng.randint(a, b)\n            if v != 0:\n                return v\n\n    def choice(seq):\n        return rng.choice(list(seq))\n\n    def sample(seq, k):\n        return rng.sample(list(seq), k)\n\n    def shuffled(seq):\n        items = list(seq)\n        rng.shuffle(items)\n        return items\n\n    def randlist(n, a, b, distinct=False):\n        """Liste de n entiers aléatoires dans [a, b] (distincts si demandé)."""\n        if distinct:\n            return rng.sample(range(a, b + 1), n)\n        return [rng.randint(a, b) for _ in range(n)]\n\n    def randword(length=None, alphabet=string.ascii_lowercase):\n        length = length or rng.randint(4, 7)\n        return "".join(rng.choice(alphabet) for _ in range(length))\n\n    def randname(pool=None, k=None):\n        pool = list(pool or NOMS_VARIABLES)\n        return rng.choice(pool) if k is None else rng.sample(pool, k)\n\n    def coin(p=0.5):\n        return rng.random() < p\n\n    return {\n        "rng": rng, "random": rng, "randint": randint, "randnz": randnz, "choice": choice,\n        "sample": sample, "shuffled": shuffled, "randlist": randlist, "randword": randword,\n        "randname": randname, "coin": coin, "uniform": rng.uniform, "randrange": rng.randrange,\n    }\n\n\nSTATIC_API = {\n    "run": run, "run_error": run_error, "evaluate": evaluate, "ExecutionError": ExecutionError,\n    "sql_run": sql_run, "sql_value": sql_value, "sql_table": sql_table, "sql_schema": sql_schema,\n    "sql_insert": sql_insert, "sql_quote": sql_quote, "md_table": md_table,\n    "tobase": tobase, "frombase": frombase, "twos": twos, "from_twos": from_twos, "group": group,\n    "code_block": code_block, "indent": indent, "dedent": dedent, "fr": fr,\n    "PRENOMS": PRENOMS, "FRUITS": FRUITS, "VILLES": VILLES, "NOMS_VARIABLES": NOMS_VARIABLES,\n    "NOMS_LISTES": NOMS_LISTES, "NOMS_FONCTIONS": NOMS_FONCTIONS,\n    "math": math, "string": string, "textwrap": textwrap,\n}\n\n\ndef seed_global_random(seed):\n    """Le module `random` global est aussi seedé : un `import random` reste déterministe."""\n    _random_module.seed(seed)\n',
    'core': '"""Génération d\'instances de questions et correction des réponses.\n\nUn modèle (template) est un dict JSON :\n{\n  "code": "code Python générateur (utilise randint, choice, ...)",\n  "statement": "énoncé Markdown avec des {{ expressions }}",\n  "fields": [ {"type": "number" | "text" | "choice" | "code" | "sql", ...}, ... ],\n  "solution": "correction Markdown avec des {{ expressions }} (facultatif)"\n}\nVoir docs/QUESTION_FORMAT.md pour la référence complète.\n"""\n\nimport ast\nimport builtins\nimport contextlib\nimport copy\nimport hashlib\nimport io\nimport json\nimport math\nimport random\nimport re\nimport signal\nimport sqlite3\nimport traceback\nimport unicodedata\n\nfrom . import helpers, sandbox\n\nFIELD_TYPES = ("number", "text", "choice", "code", "sql")\nMAX_RETRIES = 200\n\n\nclass TemplateError(Exception):\n    """Erreur dans le modèle de question (à afficher au professeur)."""\n\n    def __init__(self, message, where=None, line=None):\n        super().__init__(message)\n        self.where = where\n        self.line = line\n\n    def to_dict(self):\n        return {"error": str(self), "where": self.where, "line": self.line}\n\n\nclass Retry(Exception):\n    """Levée par reject()/require() pour tirer de nouvelles valeurs."""\n\n\nclass TimeLimit(Exception):\n    pass\n\n\n@contextlib.contextmanager\ndef time_limit(seconds):\n    """Interrompt le code après `seconds` secondes (Unix uniquement, thread principal)."""\n    if not hasattr(signal, "setitimer"):\n        yield\n        return\n\n    def handler(signum, frame):\n        raise TimeLimit(f"temps d\'exécution dépassé ({seconds} s)")\n\n    old = signal.signal(signal.SIGALRM, handler)\n    signal.setitimer(signal.ITIMER_REAL, seconds)\n    try:\n        yield\n    finally:\n        signal.setitimer(signal.ITIMER_REAL, 0)\n        signal.signal(signal.SIGALRM, old)\n\n\n# ---------------------------------------------------------------------------\n# Génération\n# ---------------------------------------------------------------------------\n\ndef _require(cond, *_):\n    if not cond:\n        raise Retry()\n\n\ndef _reject(*_):\n    raise Retry()\n\n\ndef _user_line(exc, filename):\n    """Numéro de ligne dans le code utilisateur `filename` où l\'exception s\'est produite."""\n    if isinstance(exc, SyntaxError) and exc.filename == filename:\n        return exc.lineno\n    line = None\n    for frame in traceback.extract_tb(exc.__traceback__):\n        if frame.filename == filename:\n            line = frame.lineno\n    return line\n\n\ndef _fmt(value):\n    if isinstance(value, bool):\n        return "True" if value else "False"\n    if isinstance(value, float) and value.is_integer() and abs(value) < 1e15:\n        return str(int(value))\n    return str(value)\n\n\n_INTERP = re.compile(r"\\{\\{(.+?)\\}\\}", re.S)\n\n\ndef render(text, ns, where):\n    """Remplace chaque {{ expression }} par sa valeur évaluée dans `ns`."""\n    if not text:\n        return ""\n\n    def repl(m):\n        expr = m.group(1).strip()\n        try:\n            return _fmt(eval(compile(expr, "<expr>", "eval"), ns))\n        except Retry:\n            raise\n        except Exception as exc:  # noqa: BLE001\n            raise TemplateError(f"{{{{ {expr} }}}} : {type(exc).__name__}: {exc}", where) from None\n\n    return _INTERP.sub(repl, text)\n\n\ndef _eval(expr, ns, where):\n    if not isinstance(expr, str) or not expr.strip():\n        raise TemplateError("expression manquante", where)\n    try:\n        return eval(compile(expr.strip(), "<expr>", "eval"), ns)\n    except Retry:\n        raise\n    except Exception as exc:  # noqa: BLE001\n        raise TemplateError(f"« {expr.strip()} » : {type(exc).__name__}: {exc}", where) from None\n\n\ndef _run_generator(template, rng):\n    ns = {"__name__": "__question__", "__builtins__": __builtins__}\n    ns.update(helpers.STATIC_API)\n    ns.update(helpers.make_random_api(rng))\n    ns["require"] = _require\n    ns["reject"] = _reject\n    code = template.get("code") or ""\n    try:\n        compiled = compile(code, "<generateur>", "exec")\n    except SyntaxError as exc:\n        raise TemplateError(f"erreur de syntaxe : {exc.msg}", "code", exc.lineno) from None\n    try:\n        with contextlib.redirect_stdout(io.StringIO()):\n            exec(compiled, ns)\n    except Retry:\n        raise\n    except TimeLimit:\n        raise\n    except Exception as exc:  # noqa: BLE001\n        raise TemplateError(f"{type(exc).__name__}: {exc}", "code", _user_line(exc, "<generateur>")) from None\n    return ns\n\n\ndef _choice_options(field, ns, where):\n    opts = field.get("options")\n    if isinstance(opts, str):\n        raw = _eval(opts, ns, where)\n        try:\n            result = [(str(t), bool(c)) for t, c in raw]\n        except (TypeError, ValueError):\n            raise TemplateError("options doit donner une liste de couples (texte, correct)", where) from None\n    elif isinstance(opts, list):\n        result = []\n        for i, o in enumerate(opts):\n            text = render(str(o.get("text", "")), ns, f"{where}.options[{i}]")\n            corr = o.get("correct", False)\n            if isinstance(corr, str):\n                corr = _eval(corr, ns, f"{where}.options[{i}].correct")\n            result.append((text, bool(corr)))\n    else:\n        raise TemplateError("options manquantes", where)\n    if len(result) < 2:\n        raise TemplateError("un QCM doit proposer au moins deux options", where)\n    if len({t.strip() for t, _ in result}) != len(result):\n        raise Retry()  # deux options identiques : on retire des valeurs\n    if not any(c for _, c in result):\n        raise TemplateError("aucune option correcte", where)\n    if not field.get("multiple") and sum(1 for _, c in result if c) != 1:\n        raise TemplateError("QCM à réponse unique : il faut exactement une option correcte "\n                            "(ou cocher « plusieurs réponses »)", where)\n    return result\n\n\ndef _build(template, seed):\n    """Construit (instance publique, données privées, espace de noms) pour une graine."""\n    if not isinstance(template, dict):\n        raise TemplateError("le modèle doit être un objet JSON")\n    fields = template.get("fields") or []\n    if not fields:\n        raise TemplateError("il faut au moins un champ de réponse", "fields")\n    rng = random.Random(seed)\n    helpers.seed_global_random(seed)\n    last_retry = None\n    for _ in range(MAX_RETRIES):\n        try:\n            ns = _run_generator(template, rng)\n            statement = render(template.get("statement", ""), ns, "statement")\n            public_fields, private_fields = [], []\n            for i, f in enumerate(fields):\n                where = f"fields[{i}]"\n                ftype = f.get("type")\n                if ftype not in FIELD_TYPES:\n                    raise TemplateError(f"type de champ inconnu : {ftype!r}", where)\n                pub = {"type": ftype, "label": render(f.get("label", ""), ns, where + ".label")}\n                priv = {}\n                if ftype == "number":\n                    pub["suffix"] = f.get("suffix", "")\n                    val = _eval(f.get("answer"), ns, where + ".answer")\n                    try:\n                        priv["expected"] = float(val)\n                    except (TypeError, ValueError):\n                        raise TemplateError(f"la réponse doit être un nombre (obtenu {val!r})", where) from None\n                elif ftype == "text":\n                    pub["multiline"] = bool(f.get("multiline"))\n                    val = _eval(f.get("answer"), ns, where + ".answer")\n                    accepted = [str(v) for v in val] if isinstance(val, (list, tuple, set)) else [_fmt(val)]\n                    if not accepted:\n                        raise TemplateError("aucune réponse acceptée", where)\n                    priv["accepted"] = accepted\n                elif ftype == "choice":\n                    options = _choice_options(f, ns, where)\n                    if f.get("shuffle", True):\n                        rng.shuffle(options)\n                    pub["options"] = [t for t, _ in options]\n                    pub["multiple"] = bool(f.get("multiple"))\n                    priv["correct"] = [i for i, (_, c) in enumerate(options) if c]\n                elif ftype == "code":\n                    pub["starter"] = render(f.get("starter", ""), ns, where + ".starter")\n                    pub["language"] = "python"\n                    if f.get("reference"):\n                        priv["reference"] = render(f["reference"], ns, where + ".reference")\n                elif ftype == "sql":\n                    pub["language"] = "sql"\n                    pub["starter"] = render(f.get("starter", ""), ns, where + ".starter")\n                    priv["setup"] = str(_eval(f.get("setup"), ns, where + ".setup"))\n                    priv["query"] = str(_eval(f.get("answer"), ns, where + ".answer"))\n                    try:\n                        helpers.sql_run(priv["setup"], priv["query"])\n                    except sqlite3.Error as exc:\n                        raise TemplateError(f"requête de référence invalide : {exc}", where) from None\n                public_fields.append(pub)\n                private_fields.append(priv)\n            solution = render(template.get("solution", ""), ns, "solution")\n            hints = [render(str(hnt), ns, f"hints[{i}]") for i, hnt in enumerate(template.get("hints") or [])\n                     if str(hnt).strip()]\n            public = {"statement": statement, "fields": public_fields,\n                      "max_tries": max_tries(template, public_fields)}\n            return public, {"fields": private_fields, "solution": solution, "hints": hints}, ns\n        except Retry as r:\n            last_retry = r\n            continue\n    raise TemplateError(f"impossible de satisfaire les contraintes (require/reject) après {MAX_RETRIES} essais",\n                        "code") from last_retry\n\n\nDEFAULT_MAX_TRIES = 3\n\n# Indices génériques, utilisés quand le modèle n\'en propose pas (un par type de champ).\nDEFAULT_HINTS = {\n    "number": "Reprenez l\'énoncé pas à pas : notez dans un tableau la valeur de chaque variable après chaque "\n              "instruction, sans sauter d\'étape.",\n    "text": "Relisez le format de réponse demandé, puis reprenez l\'exécution ligne par ligne en notant les "\n            "valeurs des variables (attention aux bornes des boucles et aux indices qui commencent à 0).",\n    "choice": "Éliminez d\'abord les propositions dont vous êtes sûr·e qu\'elles sont fausses, puis revenez à la "\n              "définition vue en cours pour départager les autres.",\n    "code": "Lisez le premier test qui échoue : il indique les arguments utilisés. Exécutez votre code à la main "\n            "sur ce cas précis et comparez avec le résultat attendu.",\n    "sql": "Construisez la requête dans l\'ordre : quelles colonnes afficher (SELECT), dans quelle(s) table(s) "\n           "(FROM, JOIN), quelles lignes garder (WHERE), puis regroupements et tri.",\n}\n\n\ndef max_tries(template, public_fields):\n    """Nombre d\'essais : `max_tries` du modèle, sinon 3 ; un seul pour un QCM à deux options\n    (un deuxième essai donnerait la réponse)."""\n    if template.get("max_tries"):\n        return max(1, min(int(template["max_tries"]), 10))\n    if all(f["type"] == "choice" and len(f["options"]) <= 2 and not f.get("multiple") for f in public_fields):\n        return 1\n    return DEFAULT_MAX_TRIES\n\n\ndef hints_for(template, priv, failed_types):\n    """Indices du modèle, ou à défaut un indice générique par type de champ faux."""\n    if priv["hints"]:\n        return priv["hints"]\n    return list(dict.fromkeys(DEFAULT_HINTS[t] for t in failed_types if t in DEFAULT_HINTS))\n\n\ndef fingerprint(public):\n    data = json.dumps(public, sort_keys=True, ensure_ascii=False).encode("utf-8")\n    return hashlib.sha256(data).hexdigest()[:16]\n\n\ndef generate(template, seed, avoid=(), max_tries=25):\n    """Instance publique pour `seed`. Si son empreinte figure dans `avoid`, on essaie\n    d\'autres graines (au plus `max_tries`) pour proposer des données jamais vues."""\n    avoid = set(avoid or ())\n    picker = random.Random(seed ^ 0x5EED)\n    best = None\n    for _ in range(max(1, max_tries)):\n        with time_limit(5):\n            public, _priv, _ns = _build(template, seed)\n        fp = fingerprint(public)\n        if best is None:\n            best = (seed, public, fp)\n        if fp not in avoid:\n            return {"seed": seed, "fingerprint": fp, "public": public, "fresh": True}\n        seed = picker.getrandbits(32)\n    seed, public, fp = best\n    return {"seed": seed, "fingerprint": fp, "public": public, "fresh": False}\n\n\ndef expected_display(field, pub, priv):\n    t = field.get("type")\n    if t == "number":\n        return helpers.fr(priv["expected"]) if not priv["expected"].is_integer() else str(int(priv["expected"]))\n    if t == "text":\n        v = priv["accepted"][0]\n        return helpers.code_block(v, "text") if "\\n" in v or pub.get("multiline") else f"`{v}`"\n    if t == "choice":\n        return "\\n".join(f"- {pub[\'options\'][i]}" for i in priv["correct"])\n    if t == "sql":\n        return helpers.code_block(priv["query"], "sql")\n    return None\n\n\ndef preview(template, seed, samples=30):\n    """Pour l\'éditeur : instance + réponses attendues + indicateur de variété."""\n    with time_limit(8):\n        public, priv, _ns = _build(template, seed)\n        public2, _, _ = _build(template, seed)\n    deterministic = fingerprint(public) == fingerprint(public2)\n    expected = [expected_display(f, p, q) for f, p, q in zip(template["fields"], public["fields"], priv["fields"])]\n    seen = set()\n    rng = random.Random(seed)\n    try:\n        with time_limit(6):\n            for _ in range(samples):\n                pub, _, _ = _build(template, rng.getrandbits(32))\n                seen.add(fingerprint(pub))\n    except TimeLimit:\n        pass\n    return {\n        "seed": seed, "fingerprint": fingerprint(public), "public": public, "expected": expected,\n        "solution": priv["solution"], "hints": priv["hints"], "variety": {"samples": samples, "distinct": len(seen)},\n        "deterministic": deterministic,\n    }\n\n\n# ---------------------------------------------------------------------------\n# Correction\n# ---------------------------------------------------------------------------\n\n_NUM = re.compile(r"^[+-]?(\\d+\\.?\\d*|\\.\\d+)(e[+-]?\\d+)?$", re.I)\n\n\ndef parse_number(text):\n    s = str(text).strip().replace("−", "-").replace(" ", "").replace("\u202f", "").replace(",", ".")\n    if "/" in s:\n        num, _, den = s.partition("/")\n        if _NUM.match(num) and _NUM.match(den) and float(den) != 0:\n            return float(num) / float(den)\n        return None\n    return float(s) if _NUM.match(s) else None\n\n\ndef _normalize_text(s, field):\n    s = str(s).replace("\\r\\n", "\\n").replace("\\r", "\\n")\n    s = "\\n".join(line.rstrip() for line in s.split("\\n")).strip("\\n").strip()\n    if field.get("ignore_case"):\n        s = s.casefold()\n    if field.get("ignore_accents"):\n        s = "".join(c for c in unicodedata.normalize("NFD", s) if unicodedata.category(c) != "Mn")\n    if field.get("ignore_spaces"):\n        s = re.sub(r"\\s+", "", s)\n    else:\n        s = re.sub(r"[ \\t]+", " ", s)\n    return s\n\n\ndef _check_number(field, priv, answer):\n    value = parse_number(answer if answer is not None else "")\n    if value is None:\n        return 0.0, "Réponse non reconnue comme un nombre."\n    exp = priv["expected"]\n    tol = float(field.get("tolerance") or 0)\n    ok = abs(value - exp) <= max(tol, 1e-9 * max(1.0, abs(exp)))\n    return (1.0 if ok else 0.0), None\n\n\ndef _check_text(field, priv, answer):\n    got = _normalize_text(answer or "", field)\n    ok = any(got == _normalize_text(a, field) for a in priv["accepted"])\n    return (1.0 if ok else 0.0), None\n\n\ndef _check_choice(field, pub, priv, answer):\n    if answer is None or answer == "":\n        chosen = set()\n    elif isinstance(answer, list):\n        chosen = {int(a) for a in answer}\n    else:\n        chosen = {int(answer)}\n    correct = set(priv["correct"])\n    if not field.get("multiple"):\n        return (1.0 if chosen == correct else 0.0), None\n    n = len(pub["options"])\n    if chosen == correct:\n        return 1.0, None\n    # QCM multiple : score partiel = proportion d\'options bien (dé)cochées, 0 si aucune cochée\n    good = sum(1 for i in range(n) if (i in chosen) == (i in correct))\n    return (round(good / n, 3) if chosen else 0.0), None\n\n\n# Attributs « magiques » autorisés dans le code élève (programmation objet courante).\n_SAFE_DUNDERS = {\n    "__init__", "__str__", "__repr__", "__len__", "__eq__", "__ne__", "__lt__", "__le__", "__gt__",\n    "__ge__", "__add__", "__sub__", "__mul__", "__truediv__", "__floordiv__", "__mod__", "__pow__",\n    "__neg__", "__iter__", "__next__", "__contains__", "__getitem__", "__setitem__", "__delitem__",\n    "__hash__", "__bool__", "__call__", "__name__", "__doc__", "__main__",\n}\n# Noms donnant accès à l\'interpréteur (ex. typing.sys, collections.abc.sys).\n_ESCAPE_NAMES = {"sys", "os", "builtins", "modules", "subprocess", "importlib", "gc", "inspect", "ctypes",\n                 "posix", "nt", "signal", "resource", "sandbox", "engine", "helpers", "core"}\n_STUDENT_IMPORTS = sandbox.ALLOWED_IMPORTS - {"sqlite3", "json", "time", "datetime", "abc", "numbers", "pprint"}\n\n\ndef _escape_usage(tree):\n    """Constructions permettant de sortir du cadre de l\'exercice (lecture de la correction...)."""\n    for node in ast.walk(tree):\n        if isinstance(node, ast.Attribute):\n            a = node.attr\n            if a in _ESCAPE_NAMES or (a.startswith("__") and a not in _SAFE_DUNDERS):\n                return f"`.{a}`"\n            if a.startswith("_") and not a.startswith("__") and not (isinstance(node.value, ast.Name) and node.value.id in ("self", "cls")):\n                return f"`.{a}`"\n        elif isinstance(node, ast.Name) and node.id.startswith("__") and node.id not in _SAFE_DUNDERS:\n            return f"`{node.id}`"\n        elif isinstance(node, ast.ImportFrom):\n            if any(al.name.startswith("_") or al.name in _ESCAPE_NAMES for al in node.names):\n                return "cet import"\n    return None\n\n\ndef _student_import(name, globals=None, locals=None, fromlist=(), level=0):\n    if level or name.split(".")[0] not in _STUDENT_IMPORTS:\n        raise ImportError(f"le module « {name} » n\'est pas disponible dans cet exercice")\n    return builtins.__import__(name, globals, locals, fromlist, level)\n\n\ndef _student_getattr(obj, name, *default):\n    if not isinstance(name, str) or name.startswith("_") or name in _ESCAPE_NAMES:\n        raise AttributeError(f"accès à l\'attribut « {name} » interdit")\n    return getattr(obj, name, *default)\n\n\ndef _student_builtins():\n    b = dict(builtins.__dict__)\n    for name in ("eval", "exec", "compile", "open", "breakpoint", "help", "globals", "vars", "memoryview",\n                 "__loader__", "__spec__"):\n        b.pop(name, None)\n    b["__import__"] = _student_import\n    b["getattr"] = _student_getattr\n\n    def no_input(prompt=""):\n        raise helpers.ExecutionError("input() n\'est pas utilisable dans cet exercice")\n\n    b["input"] = no_input\n    return b\n\n\n@contextlib.contextmanager\ndef _student_mode():\n    sandbox.STUDENT = True\n    try:\n        yield\n    finally:\n        sandbox.STUDENT = False\n\n\ndef _forbidden_usage(tree, forbid):\n    names = set(forbid or ())\n    found = set()\n    for node in ast.walk(tree):\n        if isinstance(node, ast.Name) and node.id in names:\n            found.add(node.id)\n        elif isinstance(node, ast.Attribute) and node.attr in names:\n            found.add(node.attr)\n        elif isinstance(node, (ast.Import, ast.ImportFrom)):\n            for alias in node.names:\n                if alias.name.split(".")[0] in names or "import" in names:\n                    found.add(alias.name)\n        elif isinstance(node, (ast.For, ast.While)) and ("for" in names or "while" in names):\n            kw = "for" if isinstance(node, ast.For) else "while"\n            if kw in names:\n                found.add(kw)\n    return sorted(found)\n\n\n_PLAIN = (int, float, complex, str, bytes, bool, type(None))\n\n\ndef same_value(got, expected):\n    """Égalité stricte qui ne fait pas confiance aux __eq__ définis par l\'élève."""\n    if isinstance(expected, bool) or isinstance(got, bool):\n        return type(got) is type(expected) and got == expected\n    if isinstance(expected, (int, float)) and type(got) in (int, float):\n        return got == expected or math.isclose(got, expected, rel_tol=1e-9, abs_tol=1e-9)\n    if type(got) is not type(expected):\n        return False\n    if isinstance(expected, _PLAIN):\n        return got == expected\n    if isinstance(expected, (list, tuple)):\n        return len(got) == len(expected) and all(same_value(a, b) for a, b in zip(got, expected))\n    if isinstance(expected, dict):\n        return (set(got.keys()) == set(expected.keys())\n                and all(same_value(got[k], expected[k]) for k in expected))\n    if isinstance(expected, (set, frozenset)):\n        return all(type(x) in _PLAIN or isinstance(x, tuple) for x in got) and got == expected\n    return expected == got\n\n\ndef _short(v, limit=120):\n    s = repr(v)\n    return s if len(s) <= limit else s[:limit] + "…"\n\n\ndef _check_code(field, ns, answer):\n    code = str(answer or "")\n    if not code.strip():\n        return 0.0, "Aucun code fourni."\n    try:\n        tree = ast.parse(code, "<eleve>")\n    except SyntaxError as exc:\n        return 0.0, f"Erreur de syntaxe ligne {exc.lineno} : {exc.msg}"\n    bad = _forbidden_usage(tree, field.get("forbid"))\n    if bad:\n        return 0.0, "Utilisation interdite dans cet exercice : " + ", ".join(f"`{b}`" for b in bad)\n    escape = _escape_usage(tree)\n    if escape:\n        return 0.0, f"Construction non autorisée dans les exercices : {escape}"\n\n    student_ns = {"__name__": "__main__", "__builtins__": _student_builtins()}\n    out = io.StringIO()\n    limit = float(field.get("time_limit") or 2)\n    try:\n        with contextlib.redirect_stdout(out), time_limit(limit), _student_mode():\n            exec(compile(tree, "<eleve>", "exec"), student_ns)\n    except TimeLimit as exc:\n        return 0.0, f"Votre programme ne s\'arrête pas : {exc}."\n    except helpers.ExecutionError as exc:\n        return 0.0, str(exc)\n    except BaseException as exc:  # noqa: BLE001 - y compris SystemExit\n        line = _user_line(exc, "<eleve>")\n        return 0.0, f"Erreur à l\'exécution{f\' ligne {line}\' if line else \'\'} : {type(exc).__name__}: {exc}"\n\n    results = []  # (ok, message)\n    test_ns = dict(ns)\n    test_ns.update({k: v for k, v in student_ns.items() if not k.startswith("__")})\n    test_ns["student"] = student_ns\n    test_ns["student_output"] = out.getvalue()\n\n    def check(cond, message="test"):\n        results.append((bool(cond), str(message)))\n        return bool(cond)\n\n    def check_equal(got, expected, message=None):\n        ok = same_value(got, expected)\n        results.append((ok, message or (f"obtenu {_short(got)}, attendu {_short(expected)}")))\n        return ok\n\n    test_ns["check"] = check\n    test_ns["check_equal"] = check_equal\n\n    try:\n        with contextlib.redirect_stdout(io.StringIO()), time_limit(max(limit * 3, 3)), _student_mode():\n            fname = field.get("function")\n            if fname:\n                func = student_ns.get(fname)\n                if not callable(func):\n                    return 0.0, f"La fonction `{fname}` n\'est pas définie."\n                cases = _eval(field.get("cases"), ns, "cases") if field.get("cases") else []\n                for args, expected in cases:\n                    args = args if isinstance(args, tuple) else (args,)\n                    shown = f"{fname}({\', \'.join(_short(a, 60) for a in args)})"\n                    try:\n                        got = func(*copy.deepcopy(args))\n                    except TimeLimit:\n                        raise\n                    except BaseException as exc:  # noqa: BLE001\n                        results.append((False, f"`{shown}` lève {type(exc).__name__}: {exc}"))\n                        continue\n                    ok = same_value(got, expected)\n                    results.append((ok, f"`{shown}` renvoie `{_short(got)}`" + ("" if ok else f", attendu `{_short(expected)}`")))\n            if field.get("tests"):\n                try:\n                    exec(compile(field["tests"], "<tests>", "exec"), test_ns)\n                except TimeLimit:\n                    raise\n                except AssertionError as exc:\n                    results.append((False, str(exc) or f"assertion ligne {_user_line(exc, \'<tests>\')}"))\n                except BaseException as exc:  # noqa: BLE001\n                    results.append((False, f"erreur pendant les tests : {type(exc).__name__}: {exc}"))\n    except TimeLimit as exc:\n        results.append((False, f"Trop lent : {exc}."))\n\n    if not results:\n        return 1.0, "Code exécuté sans erreur."\n    passed = sum(1 for ok, _ in results if ok)\n    lines = [f"{passed}/{len(results)} test(s) réussi(s)."]\n    shown = [m for ok, m in results if not ok][:5] if field.get("show_tests", True) else []\n    lines += [f"- ✗ {m}" for m in shown]\n    score = passed / len(results)\n    if field.get("all_or_nothing"):\n        score = 1.0 if passed == len(results) else 0.0\n    return round(score, 3), "\\n".join(lines)\n\n\ndef _norm_cell(v):\n    if isinstance(v, float):\n        return round(v, 6)\n    return v\n\n\ndef _check_sql(field, priv, answer):\n    query = str(answer or "").strip().rstrip(";").strip()\n    if not query:\n        return 0.0, "Aucune requête fournie."\n    try:\n        db = helpers.sql_connect(priv["setup"])\n    except sqlite3.Error as exc:\n        return 0.0, f"Base de l\'exercice invalide : {exc}"\n    def authorizer(action, *_):\n        if action in (sqlite3.SQLITE_ATTACH, sqlite3.SQLITE_DETACH, sqlite3.SQLITE_PRAGMA):\n            return sqlite3.SQLITE_DENY\n        return sqlite3.SQLITE_OK\n\n    try:\n        with time_limit(3):\n            db.set_authorizer(authorizer)\n            cur = db.execute(query)\n            db.set_authorizer(None)\n            got = cur.fetchmany(5001)\n            headers = [d[0] for d in (cur.description or [])]\n            exp_cur = db.execute(priv["query"])\n            expected = exp_cur.fetchall()\n            exp_ncols = len(exp_cur.description or [])\n    except TimeLimit:\n        return 0.0, "Requête trop longue."\n    except sqlite3.Error as exc:\n        return 0.0, f"Erreur SQL : {exc}"\n    except sqlite3.Warning as exc:\n        return 0.0, f"Erreur SQL : {exc}"\n    finally:\n        db.close()\n    got_n = [tuple(_norm_cell(c) for c in r) for r in got]\n    exp_n = [tuple(_norm_cell(c) for c in r) for r in expected]\n    if field.get("ordered"):\n        ok = got_n == exp_n\n    else:\n        key = lambda r: json.dumps(r, default=str)  # noqa: E731\n        ok = sorted(got_n, key=key) == sorted(exp_n, key=key)\n    preview = helpers.md_table(got[:8], headers) if headers else "(aucun résultat)"\n    more = f"\\n\\n… {len(got) - 8} ligne(s) de plus" if len(got) > 8 else ""\n    msg = f"Votre requête renvoie {len(got)} ligne(s) et {len(headers)} colonne(s)."\n    if not ok:\n        hints = []\n        if len(headers) != exp_ncols:\n            hints.append(f"le nombre de colonnes attendu est {exp_ncols}")\n        if len(got) != len(expected):\n            hints.append(f"le nombre de lignes attendu est {len(expected)}")\n        elif field.get("ordered") and sorted(got_n, key=str) == sorted(exp_n, key=str):\n            hints.append("les lignes sont bonnes mais pas dans le bon ordre")\n        if hints:\n            msg += " Indice : " + ", ".join(hints) + "."\n    return (1.0 if ok else 0.0), msg + "\\n\\n" + preview + more\n\n\ndef check(template, seed, answers):\n    """Corrige `answers` (liste alignée sur les champs) pour l\'instance de graine `seed`."""\n    with time_limit(8):\n        public, priv, ns = _build(template, seed)\n    answers = list(answers or [])\n    fields_out = []\n    total = 0.0\n    for i, (f, pub, prv) in enumerate(zip(template["fields"], public["fields"], priv["fields"])):\n        ans = answers[i] if i < len(answers) else None\n        t = f["type"]\n        if t == "number":\n            score, fb = _check_number(f, prv, ans)\n        elif t == "text":\n            score, fb = _check_text(f, prv, ans)\n        elif t == "choice":\n            try:\n                score, fb = _check_choice(f, pub, prv, ans)\n            except (TypeError, ValueError):\n                score, fb = 0.0, "Réponse invalide."\n        elif t == "code":\n            score, fb = _check_code(f, ns, ans)\n        else:\n            score, fb = _check_sql(f, prv, ans)\n        total += score\n        fields_out.append({\n            "score": score, "correct": score >= 1.0, "feedback": fb,\n            "expected": expected_display(f, pub, prv),\n        })\n    score = round(total / len(fields_out), 3) if fields_out else 0.0\n    failed = [f["type"] for f, fo in zip(template["fields"], fields_out) if not fo["correct"]]\n    return {"score": score, "correct": score >= 1.0, "fields": fields_out, "solution": priv["solution"],\n            "hints": hints_for(template, priv, failed), "max_tries": public["max_tries"],\n            "fingerprint": fingerprint(public)}\n\n\n# ---------------------------------------------------------------------------\n# Auto-test d\'un modèle (import, questions produites par une IA...)\n# ---------------------------------------------------------------------------\n\n_PY_BLOCK = re.compile(r"```python\\n(.*?)```", re.S)\n\n\ndef reference_answers(template, public, priv):\n    """Réponses « parfaites » d\'une instance ; pour un champ `code`, le code de référence est\n    `reference` (clé du champ, avec {{ }}) ou, à défaut, le premier bloc ```python de la correction."""\n    answers, missing = [], []\n    for i, (f, pub, prv) in enumerate(zip(template["fields"], public["fields"], priv["fields"])):\n        t = f["type"]\n        if t == "number":\n            answers.append(repr(prv["expected"]))\n        elif t == "text":\n            answers.append(prv["accepted"][0])\n        elif t == "choice":\n            answers.append(prv["correct"] if f.get("multiple") else prv["correct"][0])\n        elif t == "sql":\n            answers.append(prv["query"])\n        else:\n            code = prv.get("reference")\n            if not code:\n                m = _PY_BLOCK.search(priv["solution"] or "")\n                code = m.group(1) if m else None\n            if not code:\n                missing.append(i)\n            answers.append(code or "")\n    return answers, missing\n\n\ndef selftest(template, samples=20, base_seed=12345):\n    """Vérifie un modèle sur `samples` graines : génération sans erreur, variété, réponse de\n    référence acceptée, tests de code non triviaux. Renvoie un rapport (jamais d\'exception)."""\n    errors, warnings = [], []\n    fps, fields_ok = set(), True\n    rng = random.Random(base_seed)\n    seeds = [rng.getrandbits(32) for _ in range(samples)]\n    empty_sql = 0\n    code_fields = [i for i, f in enumerate(template.get("fields") or []) if isinstance(f, dict) and f.get("type") == "code"]\n    missing_ref = set()\n    trivial_passes = set()\n    done = 0\n    try:\n        with time_limit(40):\n            for seed in seeds:\n                try:\n                    public, priv, _ns = _build(template, seed)\n                except TemplateError as exc:\n                    errors.append({"seed": seed, **exc.to_dict()})\n                    if len(errors) >= 3:\n                        break\n                    continue\n                fps.add(fingerprint(public))\n                answers, missing = reference_answers(template, public, priv)\n                missing_ref.update(missing)\n                for f, prv in zip(template["fields"], priv["fields"]):\n                    if f["type"] == "sql" and not helpers.sql_run(prv["setup"], prv["query"]):\n                        empty_sql += 1\n                result = check(template, seed, answers)\n                for i, fr in enumerate(result["fields"]):\n                    if i in missing:\n                        continue\n                    if not fr["correct"] and len(errors) < 5:\n                        fields_ok = False\n                        errors.append({"seed": seed, "where": f"fields[{i}]",\n                                       "error": "la réponse de référence est refusée : " + (fr["feedback"] or "réponse incorrecte")})\n                # un code qui ne fait rien ne doit pas passer les tests\n                for i in code_fields:\n                    f = template["fields"][i]\n                    fname = f.get("function")\n                    dummy = f"def {fname}(*args, **kwargs):\\n    return None\\n" if fname else "pass\\n"\n                    probe = list(answers)\n                    probe[i] = dummy\n                    if check(template, seed, probe)["fields"][i]["correct"]:\n                        trivial_passes.add(i)\n                done += 1\n    except TimeLimit:\n        warnings.append(f"auto-test interrompu (trop long) après {done} tirage(s)")\n    for i in sorted(missing_ref):\n        warnings.append(f"fields[{i}] : pas de code de référence (clé « reference » ou bloc ```python dans la correction) : "\n                        "les tests n\'ont pas pu être vérifiés")\n    for i in sorted(trivial_passes):\n        warnings.append(f"fields[{i}] : les tests acceptent une fonction qui ne fait rien")\n    if done and empty_sql >= done / 2:\n        warnings.append("la requête de référence renvoie souvent un résultat vide")\n    if done and len(fps) < min(5, done) and not code_fields:\n        warnings.append(f"peu de variété : {len(fps)} énoncé(s) différent(s) sur {done} tirages")\n    status = "error" if errors else ("warning" if warnings else "ok")\n    return {"status": status, "samples": done, "distinct": len(fps), "errors": errors, "warnings": warnings,\n            "reference_ok": fields_ok and not errors}\n',
}


def _load():
    pkg = types.ModuleType("qa_moteur")
    pkg.__path__ = []
    sys.modules["qa_moteur"] = pkg
    for name in ("sandbox", "helpers", "core"):
        full = "qa_moteur." + name
        mod = types.ModuleType(full)
        mod.__package__ = "qa_moteur"
        mod.__file__ = "<" + full + ">"
        sys.modules[full] = mod
        exec(compile(_SOURCES[name], mod.__file__, "exec"), mod.__dict__)
        setattr(pkg, name, mod)
    return sys.modules["qa_moteur.core"]


core = _load()
generate, preview, check, selftest, TemplateError = core.generate, core.preview, core.check, core.selftest, core.TemplateError


def _main(argv):
    if len(argv) < 2:
        print(__doc__)
        return 2
    with open(argv[1], encoding="utf-8") as f:
        data = json.load(f)
    questions = data["questions"] if isinstance(data, dict) and "questions" in data else (data if isinstance(data, list) else [data])
    show = "--apercu" in argv
    worst = 0
    for i, q in enumerate(questions, 1):
        template = q.get("template", q)
        r = selftest(template, samples=20)
        mark = {"ok": "OK   ", "warning": "AVERT", "error": "ERREUR"}[r["status"]]
        worst = max(worst, {"ok": 0, "warning": 1, "error": 2}[r["status"]])
        print(f"[{mark}] {i}. {q.get('title', '(sans titre)')} : {r['samples']} tirage(s), {r['distinct']} énoncé(s) différent(s)")
        for e in r["errors"]:
            where = f" [{e.get('where')}{', ligne ' + str(e['line']) if e.get('line') else ''}]" if e.get("where") else ""
            print(f"        erreur{where} : {e['error']}")
        for w in r["warnings"]:
            print(f"        attention : {w}")
        if show and r["samples"]:
            p = preview(template, 1)
            print("        --- exemple d'énoncé ---")
            for line in p["public"]["statement"].splitlines():
                print("        " + line)
            print("        --- réponses attendues : " + " | ".join(str(x) for x in p["expected"]))
    return worst


if __name__ == "__main__":
    sys.exit(_main(sys.argv))
